mapper.select:
SELECT er.* , cp.id 'project.id', cp.`name` 'project.name', cp.short_name 'project.short_name', cp.serial_number 'project.serial_number', type.`name` expense_type_name, sd.label expense_subject_name, u.name reimburse_user_name, (SELECT name FROM sys_user WHERE bool_delete_enum = 0 AND id = er.written_by_id) written_by_name FROM contract_expense_reimburse er LEFT JOIN sys_user u ON er.reimburse_user_id = u.id AND u.bool_delete_enum = 0 LEFT JOIN contract_project cp ON er.project_id = cp.id AND cp.bool_delete_enum = 0 AND er.project_id IS NOT NULL LEFT JOIN contract_expense_type type ON er.expense_type_id = type.id LEFT JOIN sys_dictionary sd on er.expense_subject_id = sd.id AND sd.bool_delete_enum = 0 WHERE er.bool_delete_enum = 0 AND DATE_FORMAT(er.reimburse_date,'%Y') = #{year}
AND u.name like concat('%', #{reimburseUserName}, '%')
and er.expense_type_id = #{expenseTypeId}
and er.expense_subject_id = #{expenseSubjectId}
AND er.month = #{month}
order by er.id desc
